'use strict';
let codeTopic='all',codeWeek='all',codeLevel='all',codeStatus='all',codeSearch='',codePage=0;
function codeMeta(e){return CODE_LAB_META[e.id]||e;}
function codeIndent(e){return e.indent??(['c4','c5'].includes(e.id)?4:0);}
function completedCode(e,answer=e.answers[0]){return [e.before,' '.repeat(codeIndent(e))+answer,e.after].join('\n')+'\n';}
function codeTopics(){return [...TOPICS,...READING_TOPICS].filter(t=>EXERCISES.some(e=>e.topic===t.id));}
function filteredCodeExercises(){const term=codeSearch.trim().toLowerCase();return EXERCISES.filter(e=>{const meta=codeMeta(e),r=state.records[e.id],draft=state.codeDrafts?.[e.id];return (codeTopic==='all'||e.topic===codeTopic)&&(codeWeek==='all'||meta.week===Number(codeWeek))&&(codeLevel==='all'||meta.level===codeLevel)&&(codeStatus==='all'||codeStatus==='new'&&!r||codeStatus==='missed'&&r&&!r.latestCorrect||codeStatus==='solved'&&r?.latestCorrect||codeStatus==='draft'&&!!draft?.trim()&&!r?.latestCorrect)&&(!term||[e.id,e.name,e.task,e.before,e.after,topicOf(e.topic).name].join(' ').toLowerCase().includes(term));});}
function codeExerciseCard(e){const r=state.records[e.id],meta=codeMeta(e),draft=state.codeDrafts?.[e.id]?.trim();return `<button class="exercise-card code-lab-card" data-exercise="${e.id}"><span class="card-top"><span class="tag">Week ${meta.week} · ${esc(meta.level)}</span><span class="tag">${esc(topicOf(e.topic).name)}</span></span><h3>${esc(e.name)}</h3><p>${esc(e.task)}</p><span class="card-bottom"><span>${r?.latestCorrect?'✓ Solved':r?'↻ Needs another try':draft?'Draft saved':state.revealed.includes(e.id)?'Solution viewed':'One missing line · ~2–4 min'}</span><span aria-hidden="true">→</span></span></button>`;}
function renderCodeList(){const list=filteredCodeExercises();codePage=Math.min(codePage,Math.max(0,Math.ceil(list.length/PAGE_SIZE)-1));document.getElementById('code-count').textContent=list.length+' exercises';document.getElementById('code-grid').innerHTML=list.length?list.slice(codePage*PAGE_SIZE,(codePage+1)*PAGE_SIZE).map(codeExerciseCard).join(''):'<p class="empty">No exercises match. Clear a filter or try another topic.</p>';const controls=pageControls(codePage,list.length,'code').replace('examples</span>','exercises</span>');document.getElementById('code-pagination-top').innerHTML=controls;document.getElementById('code-pagination-bottom').innerHTML=controls;}
function codeHome(filter){if(filter!==undefined)codeTopic=filter;const solved=EXERCISES.filter(e=>state.records[e.id]?.latestCorrect).length,drafts=EXERCISES.filter(e=>state.codeDrafts?.[e.id]?.trim()&&!state.records[e.id]?.latestCorrect).length;paint(`<div class="intro"><span class="eyebrow">CODE LAB · WRITE · CHECK · UNDERSTAND</span><h1>Make the next line count.</h1><p>${EXERCISES.length} guided coding exercises, from Python foundations to testing, objects, and algorithms. Complete one missing line, use a hint when needed, then read the explanation and run the completed program locally.</p><p class="muted">${solved} / ${EXERCISES.length} solved · ${drafts} unfinished drafts · Instructor: Prof. Yanwei Wang</p><div class="actions"><button class="primary" id="code-continue">Continue an unfinished exercise →</button><button class="secondary" id="code-random">Choose an exercise for me</button><a class="secondary" href="downloads/eng101-code-lab-worked-programs.zip" download>Download 100 worked programs ↓</a></div></div><div class="program-toolbar"><label class="search"><input id="code-search" type="search" value="${esc(codeSearch)}" placeholder="Find a skill, program, or exercise…" aria-label="Search Code lab"></label><label class="topic-select">Topic <select id="code-topic"><option value="all">All topics</option>${codeTopics().map(t=>`<option value="${t.id}" ${codeTopic===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="topic-select">Week <select id="code-week"><option value="all">All weeks</option>${[...new Set(EXERCISES.map(e=>codeMeta(e).week))].sort((a,b)=>a-b).map(w=>`<option value="${w}" ${codeWeek===String(w)?'selected':''}>Week ${w}</option>`).join('')}</select></label><label class="topic-select">Level <select id="code-level">${[['all','All levels'],['Foundation','Foundation'],['Apply','Apply'],['Challenge','Challenge']].map(([v,n])=>`<option value="${v}" ${codeLevel===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="topic-select">Progress <select id="code-status">${[['all','All progress'],['new','Not attempted'],['draft','Draft saved'],['missed','Needs another try'],['solved','Solved']].map(([v,n])=>`<option value="${v}" ${codeStatus===v?'selected':''}>${n}</option>`).join('')}</select></label><button class="text-button" id="clear-code-filters">Clear filters</button><span class="muted" id="code-count" role="status"></span></div><div id="code-pagination-top"></div><div class="exercise-grid" id="code-grid"></div><div id="code-pagination-bottom"></div><section class="panel code-lab-note"><h2>A small exercise, a complete program.</h2><p>Try the missing line before viewing the worked answer. Every accepted reference solution has been run in Python; the browser’s guided check compares your line with those solutions. Another valid approach may differ from this checker.</p><p>After checking, copy or download the complete program and try the regression checks. Drafts stay in this tab. Viewing a solution alone does not mark an exercise as solved.</p><div class="actions"><a class="text-button" href="#debugging">Repair a complete faulty program →</a><a class="text-button" href="#readings">Explore reading examples →</a></div></section>`,'code');renderCodeList();}
function stashCodeDraft(id,value){const draft=value??document.getElementById('code-answer').value;state.codeDrafts=state.codeDrafts||{};state.codeDrafts[id]=draft;save();return draft;}
function nextCodeExercise(id){const list=filteredCodeExercises();if(!list.length)return null;const index=list.findIndex(e=>e.id===id);const next=list[index<0?0:(index+1)%list.length];return next?.id===id?null:next;}
function exercise(id,feedback=null){const e=EXERCISES.find(e=>e.id===id);if(!e){nav('code');return;}const t=topicOf(e.topic),meta=codeMeta(e),shown=feedback==='shown'||feedback==='right',draft=state.codeDrafts?.[id]??'',next=nextCodeExercise(id);paint(`<button class="back-button" data-nav="code">← All code exercises</button><div class="question-layout"><section class="question-card"><div class="question-label"><span>${esc(t.name)}</span><span>WEEK ${meta.week} · ${esc(meta.level)} · ONE LINE</span></div><h1>${esc(e.name)}</h1><p class="muted">${esc(e.task)}</p><div class="code-context">${e.before?`<pre><code>${esc(e.before)}</code></pre>`:''}<div class="blank-line">${codeIndent(e)?'↳ INDENTED ':''}YOUR LINE GOES HERE</div>${e.after?`<pre><code>${esc(e.after)}</code></pre>`:''}</div><label class="field-label" for="code-answer">Your missing line</label><textarea id="code-answer" data-id="${e.id}" class="code-input" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="# Type one line of Python…">${esc(draft)}</textarea><p class="code-info">Leading indentation and harmless spacing are ignored. Single and double quotes are accepted. Follow the task’s variable names and requested approach. Your draft is saved in this tab.</p><div class="actions"><button class="primary" id="check-code" data-id="${e.id}">Check my line →</button><button class="secondary" id="show-solution" data-id="${e.id}">Show worked solution</button><button class="text-button" id="clear-code-draft" data-id="${e.id}">Clear my line</button></div>${feedback?`<div class="feedback ${feedback==='wrong'?'incorrect':''}" role="status"><h3>${feedback==='right'?'✓ That line works.':feedback==='shown'?'A worked solution':feedback==='empty'?'Write a line first.':'Check this line once more.'}</h3>${feedback==='empty'?'<p>Use the task, context, and hint to complete the missing line.</p>':feedback==='wrong'?'<p>Check the names, operators, and required block header. Another correct Python approach may differ from the guided answers; compare it with the worked solution and run the checks locally.</p>':`<code class="answer-line">${esc(e.answers[0])}</code><p>${esc(e.explanation)}</p>${feedback==='shown'?'<p>Viewing a solution does not mark this exercise as solved.</p>':''}<h3>Complete verified program</h3><div class="code-tools"><button class="text-button" id="copy-completed-code" data-id="${e.id}">Copy program</button><button class="text-button" id="download-completed-code" data-id="${e.id}">Download .py ↓</button><span id="code-copy-status" role="status"></span></div><pre><code>${esc(completedCode(e))}</code></pre><h3>Verified output</h3><pre><code>${esc(meta.referenceOutput)}</code></pre>${e.tests?`<details class="hint"><summary>Regression checks to run after the program</summary><pre><code>${esc(e.tests)}</code></pre></details>`:''}`}</div>`:''}<details class="hint"><summary>Get a hint</summary><p>${esc(e.hint)}</p></details>${e.program?`<p><a class="text-button" href="#program/${e.program}">Study the related course program →</a></p>`:''}<div class="actions code-next-actions">${next?`<button class="primary" data-exercise="${next.id}">Next matching exercise →</button>`:'<p class="muted">No other exercises match your current filters.</p>'}<button class="secondary" data-nav="code">Back to Code lab</button><button class="text-button" data-nav="session">My session</button></div></section><aside><div class="tip-panel"><span class="topic-icon" aria-hidden="true">${t.icon||'⌘'}</span><h3>Think through the line</h3><p>${esc(t.tip)}</p><ol><li>Identify the available values.</li><li>State what this line must produce.</li><li>Check its place in the block.</li><li>Predict the result before checking.</li></ol></div><div class="queue"><strong>Your work is worth keeping.</strong><p>Return to the list and filter for saved drafts or exercises needing another try. First submissions stay in your statistics.</p></div></aside></div>`,'code',!feedback);}
function checkCode(id){const e=EXERCISES.find(e=>e.id===id),draft=stashCodeDraft(id);if(!draft.trim()){exercise(id,'empty');return;}const normalized=normalizeCode(draft);const right=normalized!==null&&e.answers.some(a=>normalizeCode(a)===normalized);record(e,right,'code');exercise(id,right?'right':'wrong');}
async function copyCompletedCode(id){const e=EXERCISES.find(e=>e.id===id),status=document.getElementById('code-copy-status');try{await navigator.clipboard.writeText(completedCode(e));status.textContent='Program copied.';}catch{status.textContent='Copy is unavailable. Select the complete program text to copy it.';}}
function downloadCompletedCode(id){const e=EXERCISES.find(e=>e.id===id),file=new Blob(['# Instructor: Prof. Yanwei Wang\n'+completedCode(e)],{type:'text/x-python;charset=utf-8'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=e.id+'.py';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.codePage!==undefined){codePage=Number(b.dataset.codePage);renderCodeList();}else if(b.id==='clear-code-filters'){codeTopic=codeWeek=codeLevel=codeStatus='all';codeSearch='';codePage=0;codeHome();}else if(b.id==='code-continue'||b.id==='code-random'){const list=filteredCodeExercises(),unfinished=list.filter(e=>!state.records[e.id]?.latestCorrect),pool=unfinished.length?unfinished:list;const draft=pool.find(e=>state.codeDrafts?.[e.id]?.trim());const chosen=b.id==='code-continue'?(draft||pool[0]):pool[Math.floor(Math.random()*pool.length)];if(chosen)nav('exercise/'+chosen.id);else document.getElementById('code-count').textContent='No matching exercises. Clear the filters to continue.';}else if(b.id==='clear-code-draft'){if(state.codeDrafts)delete state.codeDrafts[b.dataset.id];save();exercise(b.dataset.id);}else if(b.id==='copy-completed-code')copyCompletedCode(b.dataset.id);else if(b.id==='download-completed-code')downloadCompletedCode(b.dataset.id);});
document.addEventListener('input',event=>{if(event.target.id==='code-search'){codeSearch=event.target.value;codePage=0;renderCodeList();}else if(event.target.id==='code-answer'&&event.target.dataset?.id)stashCodeDraft(event.target.dataset.id,event.target.value);});
document.addEventListener('change',event=>{if(event.target.id==='code-topic')codeTopic=event.target.value;else if(event.target.id==='code-week')codeWeek=event.target.value;else if(event.target.id==='code-level')codeLevel=event.target.value;else if(event.target.id==='code-status')codeStatus=event.target.value;else return;codePage=0;renderCodeList();});
